<?php defined('ABSPATH') || exit; ?>
<div class="tj-stack"><?php foreach (['skill' => tj_t('Kỹ năng công nghệ', 'Technology skills'), 'category' => tj_t('Nhóm nghề', 'Categories'), 'position' => tj_t('Vị trí', 'Positions'), 'location' => tj_t('Địa điểm', 'Locations')] as $tax => $label) { ?><section class="tj-panel"><h2><?php echo esc_html($label); ?></h2><?php tj_form_start('save_term', 'tj-filter-row'); tj_hidden('taxonomy', 'tj_' . $tax); tj_input('name', tj_t('Tên', 'Name'), '', 'text', true); tj_button('Thêm mới', 'Add'); echo '</form>'; ?><div class="tj-table-wrap"><table class="tj-table"><thead><tr><th><?php tj_e('Tên', 'Name'); ?></th><th><?php tj_e('Số tin', 'Jobs'); ?></th><th></th></tr></thead><tbody><?php $terms = get_terms(['taxonomy' => 'tj_' . $tax, 'hide_empty' => false]); foreach (is_wp_error($terms) ? [] : $terms as $term) { ?><tr><td><?php tj_form_start('save_term', 'tj-filter-row'); tj_hidden('taxonomy', 'tj_' . $tax); tj_hidden('id', $term->term_id); tj_input('name', tj_t('Tên', 'Name'), $term->name, 'text', true); tj_button('Lưu', 'Save', 'secondary'); echo '</form>'; ?></td><td><?php echo (int)$term->count; ?></td><td><?php tj_form_start('delete_term', 'tj-inline tj-confirm'); tj_hidden('id', $term->term_id); tj_hidden('taxonomy', 'tj_' . $tax); tj_button('Xóa', 'Delete', 'danger'); echo '</form>'; ?></td></tr><?php } ?></tbody></table></div></section><?php } ?></div>
